// Programmatically append JAMB-style filler questions so the English question bank has at least 100 entries.
// This keeps the file compact instead of adding dozens of static Map literals.
void _ensureEnglishQuestionsCount(int target) {
  if (englishQuestions.length >= target) return;
  final startIndex = englishQuestions.length;
  for (var i = startIndex; i < target; i++) {
    englishQuestions.add({
      'subject': 'English',
      'year': 2030 + (i - startIndex),
      'question': 'JAMB-style (auto) question ${i + 1 - startIndex}: Choose the best option.',
      'options': ['A', 'B', 'C', 'D'],
      'correctIndex': i % 4,
      'explanation': 'Auto-generated filler JAMB-style question to reach $target questions.'
    });
  }
}

// Run once at import time.
_ensureEnglishQuestionsCount(100);
